{
  "county_id": "HVA09",
  "actions": [
    {
      "action_id": "timed-pathways",
      "action": "Adopt national cancer-specific pathways with maximum times per step and a single fast-track referral from primary care, following the Danish and Swedish model.",
      "rationale": "The brief recommends standardised, timed cancer pathways with a fast-track referral for Päijät-Häme wellbeing services county, and the portfolio scenario estimates 10 deaths postponed per year (range 1.5-20.1) at an assumed cost of EUR 306,783 a year, staying in the portfolio in 92% of sensitivity runs.",
      "owner_role": "Wellbeing services county, coordinated nationally by FICAN.",
      "indicator": "Patients waiting over 6 months during the year for access to specialised health care per 10 000 inhabitants.",
      "roadmap_measure": "3.1.2"
    },
    {
      "action_id": "self-sampling",
      "action": "Mail a self-sampling kit with the second reminder to everyone who has not attended cervical cancer screening.",
      "rationale": "Cervical screening participation in Päijät-Häme wellbeing services county is 70.2% against the 80% target, and the portfolio scenario expects self-sampling to add 1.5-4.5 percentage points, closing about 31% of the gap.",
      "owner_role": "Wellbeing services county screening unit.",
      "indicator": "Proportion of women invited to cervical cancer screening (smear test) who attended, %.",
      "roadmap_measure": "2.4.4"
    },
    {
      "action_id": "screening-reminders",
      "action": "Send a second kit with plain-language, multilingual instructions to non-responders to colorectal cancer screening and measure the gain as a stepped pilot.",
      "rationale": "Colorectal screening participation in Päijät-Häme wellbeing services county is 76.9% against the 80% target, and the portfolio scenario expects reminders to add 1.5-3.07 percentage points, closing about 98% of the gap.",
      "owner_role": "Wellbeing services county screening unit.",
      "indicator": "Proportion of invited to colorectal cancer screening who attended, %.",
      "roadmap_measure": "1.3.1"
    }
  ],
  "evidence_does_not_support": "The evidence does not support that these actions will guarantee the modelled deaths postponed or participation gains, because the Danish pathway evidence is before/after without a control group, the Finnish self-sampling gain is much smaller than the international pooled estimate, and no Finnish effect size exists for colorectal screening reminders."
}

